import os, re, json, csv
base = "/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_11"
def norm(s): return re.sub(r'\s+',' ', str(s or '')).strip()
def grab(p,t,f=0):
    m=re.search(p,t,f); return (m.group(1) if m.lastindex else m.group(0)) if m else None

# Just grep the specific files I need for keys 04, 09, 10, 11, 12 control records
def parse(fp):
    ext = fp.rsplit('.',1)[-1].lower()
    rec={'file':os.path.basename(fp),'ext':ext}
    if ext=='pdf':
        body=norm(' '.join(re.findall(r'\(([^)]*)\)\s*Tj', open(fp,'rb').read().decode('latin1','replace'))))
        rec['body']=body; rec['key']=grab(r'CBP-061-\d+',body); rec['role']=grab(r'Evidence role:\s*([a-z_]+)',body)
        rec['entity']=grab(r'ENT-061-\d+',body); rec['rr']=grab(r'Referenced revision:\s*(REV-\d+\.\d+)',body); rec['cr']=grab(r'Current revision:\s*(REV-\d+\.\d+)',body)
        return rec
    c=open(fp,encoding='utf-8',errors='replace').read()
    if ext=='json':
        j=json.loads(c); rec.update(key=j.get('portfolio_key'),role=j.get('evidence_role'),entity=j.get('immutable_entity_key'),rr=j.get('referenced_revision'),cr=j.get('current_revision'),body=norm(j.get('body')))
    elif ext=='xml':
        rec.update(key=grab(r'<portfolio-key>([^<]+)</portfolio-key>',c),role=grab(r'<evidence-role>([^<]+)</evidence-role>',c),entity=grab(r'<immutable-entity-key>([^<]+)</immutable-entity-key>',c),rr=grab(r'<referenced-revision>([^<]+)</referenced-revision>',c),cr=grab(r'<current-revision>([^<]+)</current-revision>',c),body=norm(grab(r'<native-record>(.*?)</native-record>',c,re.S)))
    elif ext=='html':
        rec.update(key=grab(r'<dt>Portfolio key</dt><dd>([^<]+)</dd>',c),role=grab(r'<dt>Evidence role</dt><dd>([^<]+)</dd>',c),entity=grab(r'<dt>Entity</dt><dd>([^<]+)</dd>',c),rr=grab(r'<dt>Revision</dt><dd>([^<]+)</dd>',c),cr=grab(r'<dt>Revision</dt><dd>([^<]+)</dd>',c),body=norm(grab(r'</dl><p>(.*?)</p>',c,re.S)))
    elif ext=='md':
        rec.update(key=grab(r'Portfolio key\s*\|\s*([A-Z]+-\d+-\d+)',c),role=grab(r'Evidence role\s*\|\s*([a-z_]+)',c),entity=grab(r'Immutable entity\s*\|\s*(ENT-\d+-\d+)',c),rr=grab(r'Referenced revision\s*\|\s*(REV-\d+\.\d+)',c),cr=grab(r'Current revision\s*\|\s*(REV-\d+\.\d+)',c),body=norm(grab(r'## Native record\n\n(.*?)\n\n## Reliance',c,re.S)))
    elif ext=='txt':
        rec.update(key=grab(r'PORTFOLIO KEY:\s*([A-Z]+-\d+-\d+)',c),role=grab(r'EVIDENCE ROLE:\s*([a-z_]+)',c),entity=grab(r'ENTITY KEY:\s*(ENT-\d+-\d+)',c),rr=grab(r'REFERENCED REVISION:\s*(REV-\d+\.\d+)',c),cr=grab(r'CURRENT REVISION:\s*(REV-\d+\.\d+)',c),body=norm(grab(r'NATIVE RECORD\n(.*?)\n\nSOURCE LINEAGE',c,re.S)))
    return rec

